(()=>{
 const FRAME_ASSETS_V228={"apex": "data:image/webp;base64,", "bronze": "data:image/webp;base64,", "diamond": "data:image/webp;base64,", "gold": "data:image/webp;base64,", "master": "data:image/webp;base64,", "platinum": "data:image/webp;base64,", "rookie": "data:image/webp;base64,", "silver": "data:image/webp;base64,"};window.tcgRankFrameAssetsV231=FRAME_ASSETS_V228;
 const FRAME_DEFS_V228=[
  {id:'rookie',name:'Rookie',min:0,color:'rgba(197,205,224,.6)',animated:false},
  {id:'bronze',name:'Bronze',min:120,color:'rgba(208,145,88,.6)',animated:false},
  {id:'silver',name:'Silver',min:250,color:'rgba(191,214,255,.62)',animated:false},
  {id:'gold',name:'Gold',min:450,color:'rgba(255,207,74,.62)',animated:false},
  {id:'platinum',name:'Platinum',min:700,color:'rgba(73,232,255,.65)',animated:true},
  {id:'diamond',name:'Diamond',min:1000,color:'rgba(102,171,255,.65)',animated:true},
  {id:'master',name:'Master',min:1400,color:'rgba(185,95,255,.65)',animated:true},
  {id:'apex',name:'Apex',min:1900,color:'rgba(255,68,131,.65)',animated:true},
 ];
 function frameState(){state.profileFramesV228=state.profileFramesV228||{owned:{},selected:'',season:1,lastClaimedSeason:0,history:[]};return state.profileFramesV228}
 function rankedPeakRp(){return Math.max(Number(state.rankedV221?.seasonHigh||0),Number(state.rankedV221?.rp||0))}
 function currentPeakRankId(){try{return window.tcgRankedV221?.currentRank?.(rankedPeakRp())?.id||'rookie'}catch(_){return 'rookie'}}
 function currentRankId(){try{return window.tcgRankedV221?.currentRank?.(Number(state.rankedV221?.rp||0))?.id||'rookie'}catch(_){return 'rookie'}}
 function defById(id){return FRAME_DEFS_V228.find(x=>x.id===id)||FRAME_DEFS_V228[0]}
 function eligibleIds(){const peak=currentPeakRankId();const idx=Math.max(0,FRAME_DEFS_V228.findIndex(x=>x.id===peak));return FRAME_DEFS_V228.slice(0,idx+1).map(x=>x.id)}
 function ensureAvatarFx(){const btn=document.getElementById('profileAvatarBtnV227');if(!btn)return null;let aura=btn.querySelector('.profileFrameAuraV228');if(!aura){aura=document.createElement('span');aura.className='profileFrameAuraV228';btn.appendChild(aura)}let frame=btn.querySelector('.profileFrameImageV228');if(!frame){frame=document.createElement('span');frame.className='profileFrameImageV228';btn.appendChild(frame)}return btn}
 function applyAvatarFrame(){const fs=frameState(),btn=ensureAvatarFx();if(!btn)return;FRAME_DEFS_V228.forEach(d=>btn.classList.remove('frame-'+d.id));btn.classList.remove('hasFrameV228','animatedV228');const sel=fs.selected&&fs.owned[fs.selected]?fs.selected:'';if(!sel){btn.style.removeProperty('--profile-frame-image');return}const def=defById(sel);btn.style.setProperty('--profile-frame-image',`url(${FRAME_ASSETS_V228[sel]})`);btn.classList.add('hasFrameV228','frame-'+sel);if(def.animated)btn.classList.add('animatedV228')}
 function claimSeasonFrames(){const fs=frameState();const ids=eligibleIds();ids.forEach(id=>fs.owned[id]=true);fs.lastClaimedSeason=Number(fs.season||1);fs.history.unshift({season:fs.lastClaimedSeason,claimedAt:Date.now(),peak:currentPeakRankId(),unlocked:ids.slice()});if(!fs.selected||!fs.owned[fs.selected])fs.selected=ids[ids.length-1]||'';save();applyAvatarFrame();renderFrameVault();if(window.tcgProfileV227?.renderIdentity)window.tcgProfileV227.renderIdentity();try{window.tcgCloudV192?.pushSilent?.()}catch(_){}if(typeof toast==='function')toast(`🏅 Unlocked ${ids.length} season frame${ids.length===1?'':'s'}`);}
 function clearFrame(){const fs=frameState();fs.selected='';save();applyAvatarFrame();renderFrameVault();if(typeof toast==='function')toast('Profile frame removed');try{window.tcgCloudV192?.pushSilent?.()}catch(_){}}
 function equipFrame(id){const fs=frameState();if(!fs.owned[id])return;fs.selected=id;save();applyAvatarFrame();renderFrameVault();try{window.tcgCloudV192?.pushSilent?.()}catch(_){}if(typeof toast==='function')toast(`Applied ${defById(id).name} frame`);}
 function sectionHTML(){const fs=frameState();const peakId=currentPeakRankId();const curId=currentRankId();const eligible=eligibleIds();const selectedDef=fs.selected&&fs.owned[fs.selected]?defById(fs.selected):null;const claimedThisSeason=Number(fs.lastClaimedSeason||0)>=Number(fs.season||1);const totalOwned=Object.values(fs.owned).filter(Boolean).length;return `<section class="profileGlassSectionV227" id="profileFramesVaultV228"><div class="frameSeasonHeroV228"><div class="frameSeasonCardV228 frameSeasonCopyV228"><small>SEASON REWARD FRAMES</small><h3>Metal Ranked Avatar Frames</h3><p>These circular metallic frames are locked season rewards. Close the season to unlock every frame up to your highest rank, then apply them to your collector profile at any time.</p><div class="frameSeasonStatsV228"><div><span>CURRENT RANK</span><b>${defById(curId).name}</b><em>Based on your live RP</em></div><div><span>SEASON PEAK</span><b>${defById(peakId).name}</b><em>${Math.round(rankedPeakRp())} RP high</em></div><div><span>FRAMES OWNED</span><b>${totalOwned} / ${FRAME_DEFS_V228.length}</b><em>${claimedThisSeason?'Season rewards claimed':'Rewards waiting at season end'}</em></div></div></div><div class="frameClaimSideV228"><div class="frameClaimBadgeV228"><div class="framePreviewV228" style="width:66px;height:66px">${selectedDef?`<span class="miniFrameV228" style="--frame-image:url('${FRAME_ASSETS_V228[selectedDef.id]}')"></span>`:''}</div><div><strong>${selectedDef?selectedDef.name+' Equipped':'No Frame Equipped'}</strong><span>${selectedDef?(selectedDef.animated?'Animated season frame with colour-matched energy.':'Season reward frame ready to show off.'):`Eligible unlocks this season: ${eligible.length} frame${eligible.length===1?'':'s'}`}</span></div></div><div class="frameClaimActionsV228"><button type="button" class="frameBtnV228" id="claimSeasonFramesV228" ${claimedThisSeason?'disabled':''}>${claimedThisSeason?'SEASON FRAMES CLAIMED':'END SEASON & UNLOCK REWARDS'}</button><button type="button" class="frameBtnV228 alt" id="clearProfileFrameV228" ${selectedDef?'':'disabled'}>REMOVE EQUIPPED FRAME</button></div></div></div><div class="frameSectionHeadV228"><div><small>LOCKED VAULT</small><h3>Apply Your Season Frames</h3><p>Platinum through Apex include animated lighting and lightning that matches the frame colour.</p></div><span>${selectedDef?selectedDef.name+' ACTIVE':'LOCKED UNTIL SEASON END'}</span></div><div class="frameVaultGridV228">${FRAME_DEFS_V228.map(def=>{const owned=!!fs.owned[def.id],equipped=fs.selected===def.id&&owned,status=equipped?'EQUIPPED':owned?'OWNED':'LOCKED',btn=owned?(equipped?'EQUIPPED':'APPLY FRAME'):'UNLOCKS AT SEASON END';return `<div class="frameGridCardV228 ${owned?'owned':''} ${equipped?'equipped':''} ${def.animated?'animated':''}" style="--frame-accent:${def.color}"><div class="framePreviewWrapV228"><div class="framePreviewV228"><span class="miniFrameV228" style="--frame-image:url('${FRAME_ASSETS_V228[def.id]}')"></span></div></div><div class="frameMetaV228"><div><strong>${def.name}</strong><small>Reward rank • ${def.name} and above</small></div><span class="frameStatusPillV228 ${equipped?'equipped':owned?'owned':''}">${status}</span></div><button type="button" class="frameApplyBtnV228 ${owned?'':'locked'}" data-frame-apply-v228="${def.id}" ${owned&& !equipped?'':'disabled'}>${btn}</button></div>`}).join('')}</div></section>`}
 function renderFrameVault(){const profile=document.querySelector('#profile');if(!profile)return;const anchor=document.getElementById('profileExtrasV221')||document.getElementById('careerGrid')||document.querySelector('.collectorIdentityV158');if(!anchor)return;let wrap=document.getElementById('profileFramesVaultWrapV228');if(!wrap){wrap=document.createElement('div');wrap.id='profileFramesVaultWrapV228';anchor.insertAdjacentElement('afterend',wrap)}wrap.innerHTML=sectionHTML();applyAvatarFrame()}
 document.addEventListener('click',e=>{if(e.target.closest('#claimSeasonFramesV228')){claimSeasonFrames();return}if(e.target.closest('#clearProfileFrameV228')){clearFrame();return}const apply=e.target.closest('[data-frame-apply-v228]');if(apply){equipFrame(apply.dataset.frameApplyV228);return}});
 const oldRender=window.renderProfile;if(typeof oldRender==='function'&&!oldRender.__v228){window.renderProfile=function(){const out=oldRender.apply(this,arguments);try{renderFrameVault();applyAvatarFrame()}catch(e){console.warn(e)}return out};window.renderProfile.__v228=true}
 const oldIdentity=window.tcgProfileV227?.renderIdentity;if(typeof oldIdentity==='function'&&!oldIdentity.__v228){window.tcgProfileV227.renderIdentity=function(){const out=oldIdentity.apply(this,arguments);try{renderFrameVault();applyAvatarFrame()}catch(e){console.warn(e)}return out};window.tcgProfileV227.renderIdentity.__v228=true}
 setTimeout(()=>{try{renderFrameVault();applyAvatarFrame()}catch(_){}},900);
 window.tcgProfileFramesV228={renderFrameVault,applyAvatarFrame,claimSeasonFrames,equipFrame,clearFrame,FRAME_DEFS_V228,FRAME_ASSETS_V228};
 const row=[...document.querySelectorAll('.settingsDataLineV158')].find(x=>x.querySelector('span')?.textContent.trim()==='Game Version');if(row?.querySelector('b'))row.querySelector('b').textContent='V228 SEASON RANK FRAMES';
})();
